import{_ as l,l as o,o as e,c as n,v as r,p as s,x as t,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"学习型优化器","description":"","frontmatter":{"title":"学习型优化器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/learned-optimizer.md","filePath":"cs/learned-optimizer.md","lastUpdated":1789023840000}'),c={name:"cs/learned-optimizer.md"};function A(B,a,h,_,m,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="学习型优化器" tabindex="-1">学习型优化器 <a class="header-anchor" href="#学习型优化器" aria-label="Permalink to &quot;学习型优化器&quot;">​</a></h1><div class="epigraph"><p>把过去计划的真实延迟与基数当训练信号，下一次搜索用模型代替或修正直方图公式；泛化失败时仍要能退回 Selinger。</p><footer>—— 据 Marcus et al. Neo；Yang et al. 学习基数；Krishnan et al.；传统 Selinger 对照</footer></div><p><a href="/cs/adaptive-query-processing">上一课</a>在单次执行中途纠偏。本课不重做监测点。缺口是跨查询的记忆：相似语句反复出现，自适应每次都付探测税。学习型优化器（learned optimizer）用历史 <code>(查询特征 → 计划, 运行时间)</code> 或学习基数估计，改变 DP 的输入或直接提议树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手工直方图与独立假设是强先验。学习模型（树、神经网络）拟合工作负载，可能在相关列、复杂谓词上更准。缺口是<strong>工作负载漂移</strong>：训练在白天报表，晚上 ETL 分布不同，模型会自信地选错。还有计划空间合法性：模型不能提议外连接左右颠倒的非法树。</p><p>与计算机栏的机器学习课分开：这里模型只服务代价或基数，不是训练 Transformer。特征是表、列、谓词、估计行数，标签是真实行数或延迟。</p><p><span class="marginnote">Neo（Marcus et al.）等把计划搜索与学习价值函数结合。学习基数估计有大量后续工作。本课只钉：学习是修正估计或搜索策略，不是取消代数指称。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两条路：① 学习基数，DP 照旧；② 学习代价或策略，引导枚举。必须保留回退：模型不可用时走直方图 + Selinger。训练数据来自 explain analyze、自适应监测、采样。过拟合到某次参数窥视，等于把计划缓存的坏处学成权重。</p><p>解释性：DBA 要能问「为什么选 NLJ」。纯黑盒在回归事故里不可运维——后课计划提示与稳定性。</p>',10)),(e(),s(E,null,{default:t(()=>[d(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20HIST%5B%22%E7%9B%B4%E6%96%B9%E5%9B%BE%E5%85%88%E9%AA%8C%22%5D%20--%3E%20MIX%5B%22%E4%B8%8E%E5%AD%A6%E4%B9%A0%E4%BC%B0%E8%AE%A1%E6%B7%B7%E5%90%88%22%5D%0A%20%20LOG%5B%22%E6%89%A7%E8%A1%8C%E5%8F%8D%E9%A6%88%22%5D%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%E5%9F%BA%E6%95%B0%E6%88%96%E4%BB%A3%E4%BB%B7%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20TRAIN%20--%3E%20MIX%0A%20%20MIX%20--%3E%20DP%5B%22DP%20%2F%20%E7%AD%96%E7%95%A5%E6%90%9C%E7%B4%A2%22%5D%0A%20%20DP%20--%3E%20FB%5B%22%E5%90%88%E6%B3%95%E8%AE%A1%E5%88%92%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>冷启动：新表无历史，必须经典统计。缓存：学习计划同样要在模式变更时失效。安全：探索（试试新计划）可能把生产打慢，通常在副本或限流下探索。</p><p>学习估计若系统性低估，灾难与经典误差同类，只是更难用「加桶」修好——要有监控估计/实际比。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲索引选择的学习版细节——下一课索引选择与下推仍以经典为主，学习可作辅。也不把自动调参整个 DBMS 当一课。</p><p>后课默认：学习模型是统计模块的插件，指称与事务不变。索引选择课处理「建哪些物理结构」，与「给定结构选哪条路」分开。</p><p>没有反馈回路的「学习」只是一次拟合，会过期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>学习修正基数或搜索，必须合法、可回退、可失效。</li><li>工作负载漂移与不可解释是运维边界。</li><li>索引选择与条件下推下一课：物理设计与改写的交界。</li><li>出处：Marcus et al. Neo；学习基数估计文献；Selinger 对照。</li></ul>',9))])}const T=l(c,[["render",A]]);export{D as __pageData,T as default};
